package bundle

import (
	"regexp"
	"strings"
)

// ExplicitAutomationProvider reports the disclosed automation provider named
// in a comment or review body. ok is true for any disclosure, including a
// generic "generated by <tool>" phrase naming no recognised provider, in
// which case provider is empty.
func ExplicitAutomationProvider(body string) (provider string, ok bool) {
	return explicitAutomationProvider(body)
}

// ProviderFromLogin reports the automation provider a bot login's name
// discloses, or "" when none is recognised.
func ProviderFromLogin(login string) string { return providerFromLogin(login) }

// FlagBotContribution sets Bot and BotTool from the recognised disclosures:
// bot reports and agent reviews are flagged with their tool. A REVIEW.md
// marker registry, which would set BotReport, is not built.
func FlagBotContribution(item *ConversationItem) {
	// A disclosure match (ok) always means automation, even when the named
	// provider is unrecognized and provider comes back "": a generic
	// "generated by <tool>" phrase is still automation. Requiring
	// provider != "" here mis-flagged an unnamed agent disclosure as a human
	// comment.
	if provider, ok := ExplicitAutomationProvider(item.Body); ok {
		item.Bot, item.BotTool = true, provider
		return
	}
	if item.Bot {
		if provider := ProviderFromLogin(item.AuthorLogin); provider != "" {
			item.BotTool = provider
		}
	}
}

var (
	htmlCodePattern       = regexp.MustCompile(`(?is)<(?:code|pre)\b[^>]*>.*?</(?:code|pre)>`)
	htmlBlockquotePattern = regexp.MustCompile(`(?is)<blockquote\b[^>]*>.*?</blockquote>`)
	inlineCodePattern     = regexp.MustCompile("`+[^`\\n]*`+")
	linkPattern           = regexp.MustCompile(`\[([^\]]+)\]\([^)]+\)`)
	referenceDefinition   = regexp.MustCompile(`(?m)^[ \t]{0,3}\[([^\]]+)\]:[ \t]*(?:<[^> \n]+>|[^ \t\n]+)(?:[ \t]+(?:"[^"\n]*"|'[^'\n]*'|\([^)\n]*\)))?[ \t]*$`)
	fullReferenceLink     = regexp.MustCompile(`\[([^\]]+)\]\s*\[([^\]]*)\]`)
	shortcutReferenceLink = regexp.MustCompile(`\[([^\]]+)\]`)
	markdownPattern       = regexp.MustCompile(`[*_~]+`)
	spacePattern          = regexp.MustCompile(`\s+`)
)

func explicitAutomationProvider(body string) (string, bool) {
	text := searchableReviewText(body)
	lower := strings.ToLower(text)
	switch {
	case regexp.MustCompile(`\bcursorautomationid\b`).MatchString(lower):
		return "Cursor", true
	case regexp.MustCompile(`\bdevin-?review-?comment\b`).MatchString(lower):
		return "Devin", true
	case regexp.MustCompile(`\bcodex-?pull-?request-?review-?summary\b`).MatchString(lower):
		return "Codex", true
	}
	for _, provider := range []struct {
		name    string
		pattern string
	}{
		{"Claude", `claude(?:\s+code)?`},
		{"Codex", `codex`},
		{"Copilot", `(?:github\s+)?copilot(?:\s+coding\s+agent)?`},
		{"Cursor", `cursor(?:\s+bugbot)?`},
		{"Devin", `devin`},
	} {
		disclosures := []*regexp.Regexp{
			regexp.MustCompile(`(?i)\bgenerated\s+(?:by|with)\s+` + provider.pattern + `\b`),
			regexp.MustCompile(`(?i)\b(?:authored|written|reviewed)\s+by\s+` + provider.pattern + `\b`),
			regexp.MustCompile(`(?i)\bautomated\s+review\s+run\s+by\s+` + provider.pattern + `\s+on\s+.+?\s+behalf\b`),
		}
		for _, disclosure := range disclosures {
			if disclosure.MatchString(text) {
				return provider.name, true
			}
		}
	}
	if regexp.MustCompile(`(?i)\bgenerated\s+by\s+[[:alnum:]]\S*`).MatchString(text) ||
		regexp.MustCompile(`(?i)\bautomated\s+review\s+run\s+by\s+[[:alnum:]]\S*`).MatchString(text) {
		return "", true
	}
	return "", false
}

func searchableReviewText(body string) string {
	body = htmlCodePattern.ReplaceAllString(body, " ")
	body = htmlBlockquotePattern.ReplaceAllString(body, " ")
	lines := strings.Split(body, "\n")
	kept := lines[:0]
	inFence, inLazyQuote := false, false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "```") || strings.HasPrefix(trimmed, "~~~") {
			inFence = !inFence
			continue
		}
		if inFence || strings.HasPrefix(line, "    ") || strings.HasPrefix(line, "\t") {
			continue
		}
		if strings.HasPrefix(trimmed, ">") {
			inLazyQuote = true
			continue
		}
		if inLazyQuote {
			if trimmed == "" {
				inLazyQuote = false
			}
			continue
		}
		kept = append(kept, line)
	}
	body = strings.Join(kept, "\n")
	body = inlineCodePattern.ReplaceAllString(body, " ")
	body = strings.ReplaceAll(body, "<!--", " ")
	body = strings.ReplaceAll(body, "-->", " ")
	body = linkPattern.ReplaceAllString(body, "$1")
	body = resolveReferenceLinks(body)
	body = markdownPattern.ReplaceAllString(body, "")
	return strings.TrimSpace(spacePattern.ReplaceAllString(body, " "))
}

func resolveReferenceLinks(body string) string {
	definitions := make(map[string]struct{})
	for _, definition := range referenceDefinition.FindAllStringSubmatch(body, -1) {
		definitions[normalizeReferenceLabel(definition[1])] = struct{}{}
	}
	body = referenceDefinition.ReplaceAllString(body, " ")
	body = fullReferenceLink.ReplaceAllStringFunc(body, func(link string) string {
		parts := fullReferenceLink.FindStringSubmatch(link)
		label := parts[2]
		if label == "" {
			label = parts[1]
		}
		if _, ok := definitions[normalizeReferenceLabel(label)]; ok {
			return parts[1]
		}
		return link
	})
	return shortcutReferenceLink.ReplaceAllStringFunc(body, func(link string) string {
		text := shortcutReferenceLink.FindStringSubmatch(link)[1]
		if _, ok := definitions[normalizeReferenceLabel(text)]; ok {
			return text
		}
		return link
	})
}

func normalizeReferenceLabel(label string) string {
	return strings.ToLower(strings.Join(strings.Fields(label), " "))
}

func providerFromLogin(login string) string {
	lower := strings.ToLower(login)
	switch {
	case strings.Contains(lower, "claude"):
		return "Claude"
	case strings.Contains(lower, "codex"):
		return "Codex"
	case strings.Contains(lower, "copilot"):
		return "Copilot"
	case strings.Contains(lower, "cursor"):
		return "Cursor"
	case strings.Contains(lower, "devin"):
		return "Devin"
	default:
		return ""
	}
}
